  if(from==='space'&&(to==='moon'||to==='mars'))state.savedSpacePlayer={...state.player};
  let nextPlayer=null;
  if(restoreSaved&&to==='campus'&&state.savedCampusPlayer)nextPlayer={...state.savedCampusPlayer};
  else if(restoreSaved&&to==='space'&&['moon','mars'].includes(from)&&state.savedSpacePlayer)nextPlayer={...state.savedSpacePlayer};
  else{const pp=scenePresencePoint(to,plan.position.x,plan.position.z);nextPlayer={...state.player,x:pp.x,y:pp.y,area:sceneArea(to)};}
  state.scene=to;state.worldId=plan.target.id;state.interior=null;state.interiorFloor=null;state.nearPortal=null;state.nearStudent=null;state.nearWorldObject=null;
  nextPlayer.area=to==='campus'?(nextPlayer.area||'central'):sceneArea(to);nextPlayer.worldId=plan.target.id;nextPlayer.scene=to;state.player=nextPlayer;
  if(to==='campus')state.savedCampusPlayer=null;if(to==='space'&&['moon','mars'].includes(from))state.savedSpacePlayer=null;if(to==='campus')state.savedSpacePlayer=null;
  document.body.dataset.scene=to;campusToggle(false);valeToggle(false);toast(toastText||transitionToast(plan,from));
  if(mode==='3d')await start3D({allowFallback:true});else await startLite(fromGather?'staff_gather_scene_switch':plan.reason||'world_transition');
  showZoneBanner(to==='campus'?(state.player.area||'central'):sceneArea(to));return true;
