  return new Promise(resolve=>{let started=performance.now(),done=false;const finish=()=>{if(done)return;done=true;cancelAnimationFrame(interplanetaryTravelRaf);interplanetaryTravelRaf=0;interplanetaryTravelFinish=null;overlay.classList.add('hidden');stage?.classList.remove('interplanetary-travel-active');state.runtime?.setInputLocked?.(false);resolve();};interplanetaryTravelFinish=finish;const tick=now=>{const progress=Math.max(0,Math.min(1,(now-started)/duration));$('interplanetary-progress-bar').style.width=`${Math.round(progress*100)}%`;$('interplanetary-travel-status').textContent=travelPhase(progress).label;if(progress>=1)return finish();interplanetaryTravelRaf=requestAnimationFrame(tick);};interplanetaryTravelRaf=requestAnimationFrame(tick);});
