function activateWorldPortal(obj){
  const plan=portalTransitionPlan(obj);if(!plan)return false;
  if(plan.source.scene==='space'&&(plan.target.scene==='moon'||plan.target.scene==='mars')){openSolarSystemModal(plan.target.scene);return true;}
  travelWorldPlan(plan,{restoreSaved:true}).catch(error=>{console.error(error);toast(`Não foi possível viajar para ${plan.target.name} agora.`);});return true;
}
