function interact(){
  if(state.runtime?.getViewpointState?.()?.active){closeViewpointPanel();toast('Você voltou à exploração do Campus.');return;}
  const activeVehicle=state.runtime?.getCampusVehicle?.();if(activeVehicle){if(activeVehicle.mobilityType==='aerial'&&activeVehicle.canExit===false){toast(`🚁 Pouse em um heliponto antes de sair • altitude ${Number(activeVehicle.altitude||0).toFixed(1)} m.`);return;}if(state.vehicleMembership){leaveNetworkVehicle().catch(()=>{});return;}state.runtime?.cancelCampusVehicle?.();toast(`${activeVehicle.name||'Veículo'} • ${activeVehicle.mobilityType==='aerial'?'voo encerrado':'passeio encerrado'}.`);return;}
  if(state.nearStudent){
    if(isStaff()&&state.nearStudent.participant_role==='student')return openStaffTarget(state.nearStudent);
    openChatWith(state.nearStudent);return;
  }
  if(state.seated){const left=state.runtime?.toggleSeat?.(state.nearSeat);toast('Você se levantou do banco.');return;}
  if(state.nearSeat){const sat=state.runtime?.toggleSeat?.(state.nearSeat);if(sat){state.localAction='sit';campusMark('sit');toast('Sentado. Pressione E para levantar.');}return;}
  if(state.nearWorldObject&&handleWorldObject(state.nearWorldObject))return;
  if(!state.nearPortal)return;const z=state.nearPortal,target=WORLD_REGISTRY.get(`village-${z.key}`);
  if(target){const plan=worldTransitionPlan(target.id,{position:target.spawn,requireConnection:true,reason:'class_village_portal'});travelWorldPlan(plan,{restoreSaved:false,toastText:`🏘️ Entrando na ${target.name}…`}).catch(error=>{console.error(error);toast('Não foi possível abrir esta Vila agora.');});return;}
  const ps=portalState(z);if(isStaff())return toast(ps.text);if(z.code!==state.currentClass?.code)return toast(`Você pode visitar ${z.label}, mas as atividades pertencem àquela turma.`);if(ps.open){document.querySelector('.game-stage')?.classList.add('portal-travel');setTimeout(()=>{document.querySelector('.game-stage')?.classList.remove('portal-travel');showActivities()},430)}else toast(ps.text);
}
