const OBSERVABILITY_SAMPLE_MS=5000;
let observabilityTimer=null;
function sampleObservability(reason='interval'){
  const diag=globalThis.__agvLobbyDiag;if(!diag?.update)return null;
  let metrics=null;
  try{metrics=deepSpaceRuntime?.getObservabilitySnapshot?.()||state.runtime?.getObservabilitySnapshot?.()||null;}catch(error){diag.record?.('observability_sample_error',{message:String(error?.message||error||'unknown').slice(0,160),reason});}
  const runtimeFps=Number(metrics?.fps||state.runtime?.getFPS?.()||diag.state?.runtime?.fps||0)||null;
  const runtimeQuality=String(metrics?.quality||state.runtime?.getQuality?.()||diag.state?.runtime?.quality||'')||null;
  const currentWorld=metrics?.worldId||state.player?.worldId||sceneArea(state.scene);
  const currentInterior=metrics?.interior??(deepSpaceRuntime?`deep-space:${selectedDeepSpaceMission}`:(state.interior||null));
  const observability={...(metrics||{}),currentWorld,currentScene:state.scene||null,currentInterior,lastSampleAt:new Date().toISOString(),sampleReason:reason};
  if(observability.frameTimeMs==null&&runtimeFps)observability.frameTimeMs=Number((1000/runtimeFps).toFixed(2));
  graphicsCalibrator.updateMemory(currentWorld,observability);diag.update({runtime:{fps:runtimeFps,quality:runtimeQuality,avatar:state.runtime?.getAvatarMode?.()||null},observability,graphicsCalibration:graphicsCalibrator.getSummary(currentWorld)});
  return observability;
}
function startObservability(){if(observabilityTimer)return;sampleObservability('start');observabilityTimer=setInterval(()=>{if(!document.hidden)sampleObservability('interval')},OBSERVABILITY_SAMPLE_MS);}

function perfUpdate(info={}){
  const reportedFps=Number(info.fps||0)||null,worldId=String(info.worldId||calibrationWorldId()),cached=globalThis.__agvLobbyDiag?.state?.observability||{},reportedQuality=String(info.quality||state.runtime?.getQuality?.()||'')||null;
  const calibrationResult=worldId==='airdrop-transit'?{status:'transient-runtime'}:graphicsCalibrator.sample({worldId,fps:reportedFps,frameTimeMs:reportedFps?1000/reportedFps:null,quality:reportedQuality,estimatedGpuMemoryMb:cached.estimatedGpuMemoryMb,jsHeapUsedMb:cached.jsHeapUsedMb,jsHeapLimitMb:cached.jsHeapLimitMb,hidden:document.hidden});
  const activeQuality=String(state.runtime?.getQuality?.()||reportedQuality||'')||null;globalThis.__agvLobbyDiag?.update?.({runtime:{fps:reportedFps,quality:activeQuality,avatar:state.runtime?.getAvatarMode?.()||null,profile:info.profile||null},observability:{frameTimeMs:reportedFps?Number((1000/reportedFps).toFixed(2)):null,currentWorld:worldId,currentScene:state.scene||null,currentInterior:state.interior||null},graphicsCalibration:{...graphicsCalibrator.getSummary(worldId),lastStatus:calibrationResult?.status||calibrationResult?.reason||null}});
  const el=$('perf-badge');if(!el)return;const fps=Number(info.fps||0),show=!!fps&&(state.graphics.showPerf||fps<42);const avatar=state.runtime?.getAvatarMode?.()==='rigged-glb'?'GLB':'PROC';el.textContent=`${fps||'—'} FPS • ${String(activeQuality||'').toUpperCase()} • ${avatar}`;el.classList.toggle('hidden',!show);el.classList.remove('warn','bad');if(fps&&fps<28)el.classList.add('bad');else if(fps&&fps<42)el.classList.add('warn');
}

